// A throwaway marketplace for the integration tests: a git repository with
// a bare origin, a root key and a signing key (encrypted, generated by the
// pinned CLI), keys/ laid out as in the real repository, the reader fixture,
// a keys.json signed by the root key, and a fake `gh` that serves CI's build
// record.
import './octipus.mjs';
import { createPrivateKey, sign as edSign } from 'node:crypto';
import { execFileSync } from 'node:child_process';
import { chmodSync, cpSync, mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { cli, REPO_ROOT } from '../scripts/lib/octi.mjs';
import { buildKeysDoc, serializeKeys } from '../scripts/keys.mjs';
import { fingerprint, keysMessage, sha256Hex } from '../scripts/sign.mjs';

export const PASS = 'correct horse battery staple\n';

export async function makeMarket(tmp) {
  const repo = join(tmp, 'repo');
  const origin = join(tmp, 'origin.git');
  const secrets = join(tmp, 'secrets');
  mkdirSync(secrets, { recursive: true });
  const passFile = join(secrets, 'passphrase');
  writeFileSync(passFile, PASS, { mode: 0o600 });
  await cli.keygen(join(secrets, 'root'), { passphrase: PASS });
  await cli.keygen(join(secrets, 'signing'), { passphrase: PASS });
  await cli.keygen(join(secrets, 'rogue'), { passphrase: PASS });
  execFileSync('git', ['init', '-q', '--bare', '-b', 'main', origin]);
  execFileSync('git', ['init', '-q', '-b', 'main', repo]);
  const g = (...args) => execFileSync('git', args, { cwd: repo, encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] }).trim();
  g('config', 'user.email', 'test@example.com');
  g('config', 'user.name', 'Test');
  g('remote', 'add', 'origin', origin);
  mkdirSync(join(repo, 'keys', 'root'), { recursive: true });
  mkdirSync(join(repo, 'keys', 'signing'), { recursive: true });
  cpSync(join(secrets, 'root.pub'), join(repo, 'keys', 'root', 'root.pub'));
  cpSync(join(secrets, 'signing.pub'), join(repo, 'keys', 'signing', 'signing.pub'));
  writeFileSync(join(repo, 'keys', 'endorsements.json'), `${JSON.stringify({ signingKeys: [{ file: 'signing/signing.pub' }], revokedKeys: [] }, null, 2)}\n`);
  for (const f of ['revoked.json', 'OCTIPUS_REF', '.gitignore']) cpSync(join(REPO_ROOT, f), join(repo, f));
  writeFileSync(join(repo, 'published.json'), '{}\n');
  cpSync(join(REPO_ROOT, 'plugins', '_template'), join(repo, 'plugins', '_template'), { recursive: true });
  cpSync(join(REPO_ROOT, 'tests', 'fixtures', 'plugins', 'reader'), join(repo, 'plugins', 'reader'), { recursive: true });
  const commitAll = (msg) => { g('add', '-A'); g('commit', '-q', '-m', msg); g('push', '-q', 'origin', 'main'); return g('rev-parse', 'HEAD'); };
  commitAll('A marketplace with the reader fixture');

  // keys.json, signed by the root key. TEST ONLY: signed here with
  // node:crypto because the pinned CLI has no `octi plugin sign-keys` yet;
  // scripts/keys.mjs itself only ever signs through the CLI.
  const keysDir = join(tmp, 'live');
  mkdirSync(keysDir, { recursive: true });
  const keysFile = join(keysDir, 'keys.json');
  const writeKeys = (doc, file = keysFile) => {
    const bytes = Buffer.from(serializeKeys(doc));
    writeFileSync(file, bytes);
    const key = createPrivateKey({ key: readFileSync(join(secrets, 'root.key'), 'utf8'), passphrase: PASS.trimEnd() });
    const sig = { alg: 'ed25519', keyId: fingerprint(readFileSync(join(secrets, 'root.pub'), 'utf8')).keyId, signature: edSign(null, keysMessage(bytes), key).toString('base64') };
    writeFileSync(`${file}.sig`, `${JSON.stringify(sig, null, 2)}\n`);
    return file;
  };
  writeKeys(buildKeysDoc({ repo }));

  // A fake gh: `run list` prints the runs, `run download` writes the record.
  const ghDir = join(tmp, 'gh');
  mkdirSync(ghDir, { recursive: true });
  const gh = join(ghDir, 'gh');
  writeFileSync(gh, `#!/bin/sh
echo "$@" >> ${JSON.stringify(join(ghDir, 'calls'))}
case "$1 $2" in
  "--version ") echo "gh version test"; exit 0;;
  "run list") cat ${JSON.stringify(join(ghDir, 'runs.json'))}; exit 0;;
  "run download") shift 2; while [ "$#" -gt 0 ]; do if [ "$1" = "--dir" ]; then mkdir -p "$2"; cp ${JSON.stringify(join(ghDir, 'build-record.json'))} "$2/build-record.json"; fi; shift; done; exit 0;;
esac
exit 1
`);
  chmodSync(gh, 0o755);
  const serveRecord = (record, runs) => {
    writeFileSync(join(ghDir, 'build-record.json'), JSON.stringify(record));
    writeFileSync(join(ghDir, 'runs.json'), JSON.stringify(runs ?? [{ databaseId: 7, status: 'completed', conclusion: 'success', headSha: record.commit, event: 'push', headBranch: 'main' }]));
    writeFileSync(join(ghDir, 'calls'), '');
  };
  const ghCalls = () => readFileSync(join(ghDir, 'calls'), 'utf8');

  return {
    repo, origin, secrets, passFile, g, commitAll, keysFile, writeKeys, gh, serveRecord, ghCalls,
    rootPub: join(secrets, 'root.pub'), signingKey: join(secrets, 'signing.key'), rogueKey: join(secrets, 'rogue.key'),
    sha256: (f) => sha256Hex(readFileSync(f)),
  };
}
